\pard\sl276\slmult1\fi0\li0\tx714\tx5109\tx6524\tx7087\ql\ri0\sb0\sa25\itap0 \plain \f1\lang1033\fs22 4\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  (ca. 5 x 10). 1056ff. {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Tr\u228 \'e4gheit}}\plain \f1\lang1033\fs22  (\plain \f1\i\lang1033\fs22 tracheit\plain \f1\lang1033\fs22 ) will einen J\u252 \'fcngling von seinem Vorhaben abhalten und h\u228 \'e4lt ihn an der Schulter fest. Spruchband: \plain \f1\i\lang1033\fs22 Du chumst dar niht.\plain \f1\lang1033\fs22  Der J\u252 \'fcngling wendet sich mit der Bitte \plain \f1\i\lang1033\fs22 Hilf von hin\plain \f1\lang1033\fs22  zu einer neben ihm stehenden Person (wohl die Allegorie \plain \f1\i\lang1033\fs22 biderwer lute lere\plain \f1\lang1033\fs22 ), die antwortet: \plain \f1\i\lang1033\fs22 Hab getingen und volge mir\plain \f1\lang1033\fs22 . In einer zweiten Gruppe wendet sich ein J\u252 \'fcngling an {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 frumkeit}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 und \plain \f1\i\lang1033\fs22 ere\plain \f1\lang1033\fs22  mit der Bitte: \plain \f1\i\lang1033\fs22 Empfahe mich ich pin e chomen\plain \f1\lang1033\fs22 , die ihm antworten: \plain \f1\i\lang1033\fs22 Wis willenchomen\plain \f1\lang1033\fs22  und \plain \f1\i\lang1033\fs22 gib mir in her\plain \f2\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Calibri;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\tx714\tx5109\tx6524\tx7087\ql\ri0\sb0\sa25\itap0 \plain \f1\lang1033\fs22 5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  (ca. 5 x 9). 1179ff. {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Eros}}\plain \f1\lang1033\fs22  (\plain \f1\i\lang1033\fs22 der mine\plain \f1\lang1033\fs22 ) zielt mit einem Pfeil auf das zweite Auge eines J\u252 \'fcnglings (\plain \f1\i\lang1033\fs22 der min man\plain \f1\lang1033\fs22 ), dem schon ein Pfeil im ersten Auge steckt, und sagt: \plain \f1\i\lang1033\fs22 Ich pin plint und mach plint.\plain \f1\lang1033\fs22  Spruch des J\u252 \'fcnglings: \plain \f1\i\lang1033\fs22 Tu weist mich wol\plain \f1\lang1033\fs22 . Daneben senkt Eros den Bogen vor einem jungen Mann (\plain \f1\i\lang1033\fs22 der weis man\plain \f1\lang1033\fs22 ), der ein Zaumzeug (vom Zeichner nicht verstanden, erschlossen aus anderen Hss.) in der Hand h\u228 \'e4lt. Eros: \plain \f1\i\lang1033\fs22 Ia soll ich dich wissen\plain \f1\lang1033\fs22 ; der J\u252 \'fcngling: \plain \f1\i\lang1033\fs22 Ich wise dich paz\plain \f2\lang1033\fs22 .}

