\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 11\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  (Ps 38) D. K\u246 \'f6nig {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 David}}\plain \f1\lang1033\fs22 , kniend und auf seinen Mund deutend; dar\u252 \'fcber das Angesicht des Herrn. \plain \f1\i\lang1033\fs22 Abb. 322\plain \f1\lang1033\fs22 .}

