\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Spiegel abgel\u246 \'f6st (vorne wie das Schutzbl. aus Papier, zu Eintr\u228 \'e4gen s. Provenienz; hinten aus Pergament mit Notae und Exzerpten, 2. H\u228 \'e4lfte 14. Jh.) und freistehend zusammen mit zwei aus dem Falz gel\u246 \'f6sten Pergamentstreifen ({\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Brevier}}\plain \f1\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 13. Jh.}}\plain \f1\lang1033\fs22 , mit Fleuronn\u233 \'e9eschmuck) eingeheftet.}

