\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Die f\u252 \'fcr Gebrauchshss. mit juristischen Texten typische, aber einfache Ausstattung l\u228 \'e4\u223 \'dft sich mit einer Reihe von Codices in Verbindung bringen, die zu Anfang oder in der 1. H\u228 \'e4lfte des 13. Jhs. wahrscheinlich in Bologna entstanden. Zu den rechtsb\u252 \'fcndig in die Textspalten gesetzten, oftmals nicht um die fig\u252 \'fcrlichen Elemente erg\u228 \'e4nzten Bl\u246 \'f6cken von Ziermajuskeln mit den begrenzenden Spiralenreihen vgl. den in Oberitalien entstandenen Grundbestand in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Fulda, HLB, D 5}}\plain \f1\lang1033\fs22  (Illum. Hss. der HLB Fulda, 1993, Kat.-Nr. 54:1. Drittel 13. Jh.; s. auch Mss. enlumin\u233 \'e9s d\rquote origine italienne 2, 1984, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Kat.-Nr. 80}}\plain \f1\lang1033\fs22 : Bologna, Anfang oder 1. H\u228 \'e4lfte 13. Jh.). Zum urspr\u252 \'fcnglichen Aussehen der bis auf wenige Details durch Rasur verlorenen Ausl\u228 \'e4ufer s. Mss. enlumin\u233 \'e9s d\rquote origine italienne 2, 1984, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Kat.-Nr. 77-93}}\plain \f1\lang1033\fs22 : Bologna (?), Anfang oder 1. H\u228 \'e4lfte 13. Jh.; zur Herkunft und Entwicklung dieser Formen vgl. ebenda, S. 63f.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

