\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 3*\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Hans Sachs}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Kurze Vermahnung zu dem Tod}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 Reimpaardichtung. \plain \f1\i\lang1033\fs24 Volgt hern\u228 \'e4ch ain erman\u252 \'fcng z\u252 \'fc dem tod.\plain \f1\lang1033\fs24  Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O mensch bedenck dein letste ze\u255 \'fft\~/ Der vngewissen sicherhait\~/ Hoffn\u252 \'fcng langs lebens ist verloren}}\plain \f1\i\lang1033\fs24 \~\plain \f1\lang1033\fs24 \u8230 \'85 32 Verse. Derselbe Text in dieser Hs. auch auf 68\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  (s.\~u.).\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 Ausgaben. Hans Sachs, hg. v. A. v. \plain \f1\scaps\lang1033\fs24 Keller\plain \f1\lang1033\fs24 , Bd. 1, T\u252 \'fcbingen 1870 (BLVS 102), S. 429 f.; J. \plain \f1\scaps\lang1033\fs24 Bolte\plain \f1\lang1033\fs24 : Das Spiegelbuch, ein illustriertes Erbauungsbuch des 15. Jh.s in dramatischer Form, in: Sitzungsberichte der Preu\u223 \'dfischen Akademie der Wissenschaften. Phil.-hist. Kl. 1932, VIII, S. 170.}

