\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Wilhelm Werner von Zimmern}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 \u220 \'dcber die rechte Lebensf\u252 \'fchrung}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 Reimpaardichtung. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Wellend ier menschen selig werden\~/ Ier m\u252 \'fcsend Lassen s\u252 \'fcnd a\u252 \'fcf erden}}\plain \f1\i\lang1033\fs24 \~/ Le\u255 \'ffplich gel\u252 \'fcst vnd fr\u246 \'f6lickait\~\plain \f1\lang1033\fs24 \u8230 \'85 166 Verse. Akrostichon: \plain \f1\i\scaps\lang1033\fs24 wilhelm wernher grave vnd her zvo zimbern her zvo wildenstayn kaiserlicher mayestat kammerrichter amptzverwalter hat dises gedicht zvo wimpfen gemacht in dem iar als man zalt nach cristi gebvrte.\plain \f1\lang1033\fs24  Nicht ganz eindeutig das Chronogramm: \plain \f1\i\lang1033\fs24 Et \plain \f1\b\i\lang1033\fs24 c\plain \f1\i\lang1033\fs24 etera zwa\plain \f1\b\i\lang1033\fs24 i\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 C\plain \f1\i\lang1033\fs24 reutz \plain \f1\b\i\lang1033\fs24 C\plain \f1\i\lang1033\fs24 hr\plain \f1\b\i\lang1033\fs24 i\plain \f1\i\lang1033\fs24 st\plain \f1\b\i\lang1033\fs24 i\plain \f1\i\lang1033\fs24  spr\plain \f1\b\i\lang1033\fs24 ic\plain \f1\i\lang1033\fs24 h .\plain \f1\b\i\lang1033\fs24 xxvi\plain \f1\i\lang1033\fs24 . A\plain \f1\b\i\lang1033\fs24 m\plain \f1\i\lang1033\fs24 en\plain \f1\lang1033\fs24 : 1540. \plain \f1\scaps\lang1033\fs24 Heiss\plain \f1\lang1033\fs24 , S. 64, errechnet 1539; ebenso bringt die Fassung in der \lquote Zimmernschen Chronik\rquote  am Ende den Zusatz \plain \f1\i\lang1033\fs24 Macht 1539\plain \f1\lang1033\fs24  und gibt an, das Gedicht sei \plain \f1\i\lang1033\fs24 anno 1539 zu Wimpfen\plain \f1\lang1033\fs24  entstanden. Das Reichskammergericht hatte sich 1539\endash 40 wegen der Pest nach Wimpfen begeben; vgl. B. R. \plain \f1\scaps\lang1033\fs24 Jenny\plain \f1\lang1033\fs24 : Graf Froben Christoph von Zimmern, Lindau/Konstanz 1959, S. 60.\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 Ausgaben. \plain \f1\scaps\lang1033\fs24 Heiss\plain \f1\lang1033\fs24 , S. 57\endash 62; Zimmerische Chronik, a.\~a.\~O., Bd. 4, S. 233\endash 237; \plain \f1\scaps\lang1033\fs24 Kiening,\plain \f1\lang1033\fs24  Totentanz, S. 146\endash 150.}

