\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 182\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 223\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 230\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 183\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Speculum artis bene moriendi}}\plain \f1\scaps\lang1033\fs24  \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 dt.\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 Erweiternde dt. Bearbeitung der in Hss. und Fr\u252 \'fchdrucken stark \u252 \'fcberlieferten lat. Sterbekunst. Unter den zahlreichen dt. \u220 \'dcbersetzungen und Bearbeitung scheint die hier vorliegende Fassung unikal \u252 \'fcberliefert zu sein. \plain \f1\i\lang1033\fs24 Dises nach\u252 \'fcolgend b\u252 \'fcchle w\u252 \'fcrt geha\u255 \'ffssen oder genennet/ ain Spiegel der kranncken/ Dan darinn mag der mensch also ges\u252 \'fcnd vnd a\u250 \'fach krannck lernen vnd scha\u252 \'fcwen/ wie er sich schicken vnd beraiten soll\~\plain \f1\lang1033\fs24 \u8230 \'85 (147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Wie man soll lernen sterben\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 Mensch gedenck in allen de\u255 \'ffnen wercken de\u255 \'ffner letsten ze\u255 \'fft\~\plain \f1\lang1033\fs24 \u8230 \'85 Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sa\u255 \'fften mal das allen menschen nichtz gewissers ist wann der tod}}\plain \f1\i\lang1033\fs24 / vnd doch nichtz vngewissers dann die st\u252 \'fcnde des todes\~\plain \f1\lang1033\fs24 \u8230 \'85 (170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 O wilhelm bedracht.\plain \f1\lang1033\fs24  Textanfang: \plain \f1\i\lang1033\fs24 Ich leb vnd wa\u255 \'ff\u223 \'df nit wie lanng\~\plain \f1\lang1033\fs24 \u8230 \'85 Vgl. oben fol. 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . (182\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Auf dem Fu\u223 \'dfsteg: \plain \f1\i\lang1033\fs24 Nota hie ist das b\u250 \'fach mit den q\u252 \'fcaternen versetzet vnd die gebet so hie her geh\u246 \'f6rend m\u250 \'fa\u223 \'df man her nach suchen an dem 223. blat.\plain \f1\lang1033\fs24  (223\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 \u8250 \'9bMerck von a\u255 \'ffnem gar ha\u255 \'ffligen bapst/ vnd se\u255 \'ffnem Caplon/ a\u252 \'fcch von den dre\u250 \'faw pater nostern.\plain \f1\lang1033\fs24  Textanfang: \plain \f1\i\lang1033\fs24 Wie vorh\u255 \'ffn a\u252 \'fcch angeza\u255 \'ffgt ist worden/ Das die aller best ertzne\u255 \'ff/ die der mensch haben mag/ zw se\u255 \'ffnen letsten ze\u255 \'fften ist dise\~\plain \f1\lang1033\fs24 \u8230 \'85 (230\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Auf dem Fu\u223 \'dfsteg: \plain \f1\i\lang1033\fs24 Dises gebet must\u252 \'fc suchen hie vornen an dem 183. blat dan die q\u252 \'fcatern in dem einbinden versetzt worden sind.\plain \f1\lang1033\fs24  Literatur. K. \plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24 : \lquote Speculum artis bene moriendi\rquote , in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 9, 1995, Sp. 40\endash 49, hier Sp. 46 (III. 3. c.).}

