\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Geistliche {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lieder}}\plain \f1\lang1033\fs24 . (157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 \u225 \'e1{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ambrosius Blarer}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Wie\rquote s Gott gef\u228 \'e4llt, so gf\u228 \'e4llts mir auch}}\plain \f1\scaps\lang1033\fs24 .\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\scaps\lang1033\fs24  HEKG 281. \plain \f1\i\lang1033\fs24 Ain Christlich Liedt, darin man alle sachen dem gnedigen willen Gottes befilcht. Im thon O Herre Gott dein G\u246 \'f6ttlich wortt. \plain \f1\lang1033\fs24 Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Wies Gott gef\u246 \'f6llt so gf\u246 \'f6lts mir auch,\~/ Vnd la\u223 \'df mich gar nichts Irren}}\plain \f1\i\lang1033\fs24 \~/ Ob mich zu zeitten beist der rauch\plain \f1\lang1033\fs24 \~\u8230 \'85 8 Str. \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  III Nr. 651. A. Blarer (1492\endash 1564); vgl. M. \plain \f1\scaps\lang1033\fs24 Sobiela-Caanitz\plain \f1\lang1033\fs24 , in: \plain \f1\scaps\lang1033\fs24 Herbst\plain \f1\lang1033\fs24 , S. 41\~f. u. Cod. Don. B\~IV\~1. Literatur. F. \plain \f1\scaps\lang1033\fs24 Spitta\plain \f1\lang1033\fs24 : Das Gesangbuch Ambrosius Blaurers. Ein Beitrag zur hymnologischen Geschichte der Schweiz im Reformationszeitalter, in: Zeitschrift f\u252 \'fcr Kirchengeschichte 38, 1920, S. 238\endash 261; M. \plain \f1\scaps\lang1033\fs24 Jenny\plain \f1\lang1033\fs24 : Ambrosius Blarer als Dichter und Hymnologe, in: Der Konstanzer Reformator Ambrosius Blarer 1492\endash 1564, hg. v. B. \plain \f1\scaps\lang1033\fs24 Moeller\plain \f1\lang1033\fs24  (u.\~a.), Konstanz 1964, S. 87\endash 113. \endash  (158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Im Anschlu\u223 \'df eine einzelne Strophe: \plain \f1\i\lang1033\fs24 Ich hoff auf den herren Jesum Christ,\~/ Der mein Trost hail vnd leben ist\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  (159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 \u225 \'e1{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ambrosius Blarer}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Vermanung an die Christliche Jugent zum Gesang}}\plain \f1\lang1033\fs24 .\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ain Sch\u246 \'f6n lied vom lob des gsangs vnd Musick Im thon behalt vns herr.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Wollauf du Jungs fr\u246 \'f6liches bluet,\~/ Inn Gottes Lehr hab lust vnd mueth}}\plain \f1\i\lang1033\fs24 \~/ Mit leib vnd seel ergib dich Im\plain \f1\lang1033\fs24 \~\u8230 \'85 12 numerierte Str. \plain \f1\scaps\lang1033\fs24 Wa\plain \f1\scaps\lang1033\fs24 \-\plain \f1\scaps\lang1033\fs24 cker\plain \f1\scaps\lang1033\fs24 \-\plain \f1\scaps\lang1033\fs24 nagel\plain \f1\lang1033\fs24  III Nr. 661 (nur 8 Str.).\plain \f1\lang1033\fs20  \endash  (\plain \f1\lang1033\fs24 159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 \u225 \'e1{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Caspar Schmucker}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Wer Gott vertraut, hat wohl gebaut}}\plain \f1\lang1033\fs24 .\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ain hipsch Gaistlich lied gemacht von herrn M. S. 1584 Inn der Melodey Erzirne dich nit du fromer Christ.\plain \f1\lang1033\fs24  Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Frisch auf mein Seel verzage nit,\~/ Gott will sich dein erbarmen}}\plain \f1\i\lang1033\fs24 ,\~/ Rath hillff wirt er dir thailen mitt,\~/ er ist ain schutz der Armen\plain \f1\lang1033\fs24 \~\u8230 \'85 8 numerierte Str. \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  V Nr. 1. \endash  (160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ein lied zu Gott, dem Vatter, Sun vnnd Heiligem Geist}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Ain Sch\u246 \'f6n Gaistlich Lied.\plain \f1\lang1033\fs24  Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O Herre Gott ich ruef zu dir,\~/ O Treuwer Vatter hilff du mir}}\plain \f1\i\lang1033\fs24 ,\~/ sich an mein gross ellende\plain \f1\lang1033\fs24 \~\u8230 \'85 17 numerierte Str. \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  III Nr. 1253 (21 Str.). \endash  (161\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Leon}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ich hab mein sach Gott heimgestellt}}\plain \f1\scaps\lang1033\fs24 . HEKG 315.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ain Sch\u246 \'f6ns Liedt zum Leben vnd sterben.\plain \f1\lang1033\fs24  Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich hab mein sach Gott haim gestelt,\~/ Er machts mit mir wies Im gef\u246 \'f6llt}}\plain \f1\i\lang1033\fs24 \~/ Soll ich alhier noch lenger leben\plain \f1\lang1033\fs24 \~\u8230 \'85 18 Str. \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  IV Nr. 712. J. Leo (\u8224 \'86\~1597); vgl. ADB 18, 1883, S. 298\~f. \endash  (163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 \u225 \'e1{\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Bartholom\u228 \'e4us Ringwaldt}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Noch ein Lied, vmb bestendigen Glauben}}\plain \f1\lang1033\fs24 .\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ain Sch\u246 \'f6n Gaistlich Tr\u246 \'f6stlich Landsknecht Liedt, auch sonst allen Christen nuzlich.\plain \f1\lang1033\fs24  Textanfang: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herr Jesu Christ ich weiss gar wol,\~/ Das ich ain mal mues sterben}}\plain \f1\i\lang1033\fs24 ,\~/ Wann aber das geschechen soll\plain \f1\lang1033\fs24 \~\u8230 \'85 9 numerierte Str. \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  IV Nr. 1473. B. \plain \f1\scaps\lang1033\fs24 Ringwaldt\plain \f1\lang1033\fs24  (um 1530\endash 1599); vgl. K. \plain \f1\scaps\lang1033\fs24 Dienst\plain \f1\lang1033\fs24 , in: \plain \f1\scaps\lang1033\fs24 Bautz\plain \f1\lang1033\fs24  8, 1994, Sp. 384\~f.; J. \plain \f1\scaps\lang1033\fs24 Block\plain \f1\lang1033\fs24 , in: \plain \f1\scaps\lang1033\fs24 Herbst\plain \f1\lang1033\fs24 , S. 256\~f.}

