\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 176\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Reimpaar{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 gebete}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Volgen Ettliche sch\u246 \'f6ne sprich Reimen wey\u223 \'df.\plain \f1\lang1033\fs24  (171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Nikolaus Selnecker}}\plain \f1\scaps\lang1033\fs24 : Gebet zu\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 Psalm 51.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Gebett \u252 \'fcber den 51 Psalm.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach Gott wie bin ich so vnwerdt\~/ Im himmel vnd auch auf der Erdt}}\plain \f1\lang1033\fs24 \~\u8230 \'85  122 Reimpaarverse. N. Selnecker (1530\endash 1592); vgl. K. \plain \f1\scaps\lang1033\fs24 Loscher\plain \f1\lang1033\fs24 , in: \plain \f1\scaps\lang1033\fs24 Herbst\plain \f1\lang1033\fs24 , S. 297\~f.; W. \plain \f1\scaps\lang1033\fs24 Sommer\plain \f1\lang1033\fs24 , in: \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 RGG 7, 2004, Sp. 1187. Druck: N. \plain \f1\scaps\lang1033\fs24 Selnecker\plain \f1\lang1033\fs24 : Der Psalter mit kurtzen Summarien/ vnd Gebetlein f\u252 \'fcr die Hausueter vnd jhre Kinder, Leipzig: Hans Steinman 1581, Bl. L\~iii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash L\~v\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (zahlreiche weitere Ausgaben). (174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Nikolaus Selnecker}}\plain \f1\scaps\lang1033\fs24 : Gebet zu Psalm 103\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Volgt \u252 \'fcber den 103 Psalm.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dich Loben wir du Trewer Gott,\~/ Der du vns hilffst aus aller Nott}}\plain \f1\lang1033\fs24 \~\u8230 \'85 68 Reimpaarverse. Druck. \plain \f1\scaps\lang1033\fs24 Selnecker\plain \f1\lang1033\fs24 , a.\~a.\~O., Bl. Dd\~iv\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash Dd\~v\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . (175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Nikolaus Selnecker}}\plain \f1\scaps\lang1033\fs24 : Gebet zu Psalm 119\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Volgt \u252 \'fcber den 119 Psalm.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gleich wie ain rechter Arbaits Mann,\~/ wann er sein weinberg sichet ahn}}\plain \f1\lang1033\fs24 \~\u8230 \'85 32 Reimpaarverse. Druck. \plain \f1\scaps\lang1033\fs24 Selnecker\plain \f1\lang1033\fs24 , a.\~a.\~O., Bl. Kk\~v\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash Kk\~vi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . (176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ain Anders St. Hieronimus.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gott geb ich Ess, schlaff oder wach,\~/ Vnd was ich sonsten immer mach}}\plain \f1\lang1033\fs24 \~\u8230 \'85 14 Reimpaarverse. (176\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ain Sch\u246 \'f6n Gebett.\plain \f1\lang1033\fs24  Textanfang:\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach Herr du trewer Gott,\~/ Inn meiner angst vnd Noth}}\plain \f1\i\lang1033\fs24 \~/ Wirdt mir lanng zeit die weil\plain \f1\lang1033\fs24 \~\u8230 \'85 25 Reimpaarverse.}

