\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 Pseudo-Bernardus <\plain \f1\scaps\lang1033\fs24 Claraevallensis>\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Tractatus ad laudem gloriosae virginis matris}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 >\plain \f1\i\lang1033\fs24 Ave maria gratia plena dominus tecum.\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sillabas celestibus sacramentis plenas ore polluto proferre}}\plain \f1\i\lang1033\fs24 \~\plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 inchoasti intercedendo perficias Amen.\plain \f1\lang1033\fs24  Hier ohne Verfasserzuschreibung. Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mailand, Biblioteca Ambrosiana, Cod. E 69 Sup.}}\plain \f1\lang1033\fs24 , fol. 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; vgl. L. \plain \f1\scaps\lang1033\fs24 Jordan\plain \f1\lang1033\fs24 : Inventory of the Western Manuscripts in the Biblioteca Ambrosiana, Bd. 3, Notre Dame, Indiana 1989, S. 119. Ausgabe. PL 182, Sp. 1141\endash 1148.}

