\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 328\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Exzerpte. (328\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Richardus de S. Victore}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De praeparatione animi ad contemplationem}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  LVI. \plain \f1\i\lang1033\fs24 Geradus\plain \f1\lang1033\fs24  \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\i\lang1033\fs24  de sancto victore. Debet mens sui criminis conscia et de sua infirmitate confusa\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 prouideat de futuro.\plain \f1\lang1033\fs24  PL 196, Sp. 41. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Richardus de S. Victore}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De statu hominis interioris}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Tract.1 cap. 10. \plain \f1\i\lang1033\fs24 Salomon. Ad locum unde exeunt\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 quantitas non exuperat.\plain \f1\lang1033\fs24  PL 196, Sp.\~1123B\endash 1124B. (328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Tract. 1 cap. 3. \plain \f1\i\lang1033\fs24 Inter omnia creationis bona nihil in homine sublimius\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 creatura potest.\plain \f1\lang1033\fs24  PL 196, Sp.\~1118C\endash D. (328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 329\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) cap. XI\endash XIII. \plain \f1\i\lang1033\fs24 Omen caput languidum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 poena amitti vel minui poterit.\plain \f1\lang1033\fs24  PL 196, Sp. 1124C\endash 1126B. (329\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) cap. XIV. \plain \f1\i\lang1033\fs24 Quere obsecro\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 ad similitudinem.\plain \f1\lang1033\fs24  PL 196, Sp.\~1226C. (329\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 330\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) cap. XVII\endash XIX. \plain \f1\i\lang1033\fs24 Quamdiu caro concupiscit\plain \f1\lang1033\fs24 \~\u8230 \'85\~\endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 cum sublleuantis manus subtrahitur.\plain \f1\lang1033\fs24  PL 196, Sp. 1128C\endash 1130B. (330\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Richardus de S. Victore}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De praeparatione animae ad contemplationem}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Lib. I cap. XXII. \plain \f1\i\lang1033\fs24 Sicut ad ofitium dan spectat\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 consueuit oculos cordium.\plain \f1\lang1033\fs24  PL 196, Sp. 15B\endash D. (330\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Lib. III cap. XIII. \plain \f1\i\lang1033\fs24 Cognosce queso homo dignitatem tuam\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 factum est sub tributo.\plain \f1\lang1033\fs24  PL 196, Sp. 123A\endash B. (330\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 331\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. III cap. XXIV. \plain \f1\i\lang1033\fs24 In quinto huius contemplationis gradu\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 documenti modum expleuimus.\plain \f1\lang1033\fs24  PL 196, Sp.\~133C\endash 136A. (331\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Petrus Damiani}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Epistolae}}\plain \f1\scaps\lang1033\fs24 . XXXII.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ager ergo pigri et stulti hominis\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 arietibus dissipatur.\plain \f1\lang1033\fs24  PL 144, Sp. 144, Sp. 427B. IX. \plain \f1\i\lang1033\fs24 In cuius enim corde radicem\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 undique cohibetur.\plain \f1\lang1033\fs24  PL 144, Sp.\~388D. \plain \f1\i\lang1033\fs24 Nitimur humiliter loqui\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 nullus ualet aurire.\plain \f1\lang1033\fs24  PL 144, Sp. 389C. (331\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 332\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) XXXII. \plain \f1\i\lang1033\fs24 Fratribus in gamtini \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 heremo constitutis\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 nos debeant atestatione tueri.\plain \f1\lang1033\fs24  PL 144, Sp.\~422C\endash 423B. (332\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 XXXIII 13.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Erudiendos enim electos\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 datus est.\plain \f1\lang1033\fs24  PL 76, Sp.\~690C und weitere Zitate aus den Moralia. {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Petrus Damiani}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sermo}}\plain \f1\scaps\lang1033\fs24  XVIII.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Nec sibi quisquam de solo sibi signo crucis\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 percipite regnum.\plain \f1\lang1033\fs24  PL 144, Sp.\~610C\endash D. (332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Petrus Damiani}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sermones}}\plain \f1\scaps\lang1033\fs24 . XLVIII. \plain \f1\i\lang1033\fs24 Illa cibum hanelabat\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 pernicie liberatur.\plain \f1\lang1033\fs24  PL 144, Sp.\~767B. \plain \f1\scaps\lang1033\fs24 XLVIII. \plain \f1\i\lang1033\fs24 Crux est concordia scripturarum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 ressurectionis gloriam suscitauit.\plain \f1\lang1033\fs24  PL 144, Sp.\~771C\endash D.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 LXIV.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Qui titulis angelige dignitatis honorari sperat in patria dignitatis locum in exilio non requirat.\plain \f1\lang1033\fs24  PL 144, Sp. 875B. \plain \f1\scaps\lang1033\fs24 Pseudo-Augustinus: {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Liber de spiritu et anima}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Cap. 25. \plain \f1\i\lang1033\fs24 Quinque sunt genera sompniorum secundum augustinum: Oraculum, visio, sompnium, insompnium, phantasma\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 uel artes uel infirmitates.\plain \f1\lang1033\fs24  PL 40, Sp.\~798.}

