\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 338\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 341\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Petrus <Damiani>}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sermo}}\plain \f1\scaps\lang1033\fs24  XLVIII\plain \f1\lang1033\fs24 . Exzerpt. \plain \f1\i\lang1033\fs24 Salve o beata crux que illum meruisti nova libratione\~\plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 natoque qui a mortuis surrexit ac paraclito in seculorum secula\plain \f1\lang1033\fs24 . PL 144, Sp. 776.}

