\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 371\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Hugo }}{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u225 \'e1}}{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 de Sancto Victore}}{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u241 \'f1}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Expositio in hierarchiam coelestem Dionysii}}\plain \f1\scaps\lang1033\fs24  Areopagitae.\plain \f1\lang1033\fs24  Lib. VI. Exzerpte. //\plain \f1\i\lang1033\fs24 ardeant, et si non equaliter.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Quod autem ait recaleficans \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\i\lang1033\fs24  et resuscitans non ita intelligendum est \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 holocaustum enim est quia\plain \f1\lang1033\fs24  \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\i\lang1033\fs24  totum incenditur et totum crematur.\plain \f1\lang1033\fs24  PL 175, Sp.\~1042\endash 1044. {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Cassianus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Collationes}}\plain \f1\lang1033\fs24 . VI 12\endash 13. \plain \f1\i\lang1033\fs24 Abbas Tehodorus \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\i\lang1033\fs24 . Itaque mens uiri iusti non debet esse similis cere\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 qualitate persistere.\plain \f1\lang1033\fs24  CSEL 13, S.\~172\~f. {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Bernardus }}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u225 \'e1}}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Claraevallensis}}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u241 \'f1}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sermones super cantica canticorum}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  XXIII\~14. \plain \f1\i\lang1033\fs24 Et bene initium sapientie timor dei\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 ad sciendum.\plain \f1\lang1033\fs24  S. \plain \f1\scaps\lang1033\fs24 Bernardus\plain \f1\lang1033\fs24 : Opera, Bd. 1, hg. v. J. \plain \f1\scaps\lang1033\fs24 Leclercq/C.\~H. Talbot/H.\~M. Rochais\plain \f1\lang1033\fs24 , Rom 1957, S.\~148. {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Bernardus }}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u225 \'e1}}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Claraevallensis}}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u241 \'f1}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sententiae}}\plain \f1\lang1033\fs24 . Ser. III\~124.\plain \f1\scaps\lang1033\fs24  \plain \f1\i\lang1033\fs24 Inuenitur autem ab his qui non temptant illum. Temptare domini est in duplicitate cordis cum domino ambulare\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 illic per speciem ubi ei similes erimus.\plain \f1\lang1033\fs24  S. \plain \f1\scaps\lang1033\fs24 Bernardus\plain \f1\lang1033\fs24 : Opera, Bd. 6/2, hg. v. J. \plain \f1\scaps\lang1033\fs24 Leclercq/H.\~Rochais\plain \f1\lang1033\fs24 , Rom 1972, S.\~239.}

