\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 372\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Cassianus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Collationes}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 Exzerpte. (372\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) XIV 9. \plain \f1\i\lang1033\fs24 Abbas nestor. Inpossibile enim est eum qui proposito\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 minime consequatur \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 !\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\scaps\lang1033\fs24 . CSEL 13, S.\~408. XIV 10 \plain \f1\i\lang1033\fs24 Festinandum igitur tibi est\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 perducat.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~410. \plain \f1\lang1033\fs24 XIV 16 \plain \f1\i\lang1033\fs24 Nullus enim in quo adhuc carnalium passionum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 possidere. \plain \f1\lang1033\fs24 CSEL 13, S.\~420\~f\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 IX\~5. \plain \f1\i\lang1033\fs24 Secundum regulam seniorum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 pertinere.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~255. IX\~12. \plain \f1\i\lang1033\fs24 Oramus cum renuntiantes\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 funditus eruendas.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~261. XVIII\~13. \plain \f1\i\lang1033\fs24 Piamon. Patientia uera atque tranquilitas\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 indigebit.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~519.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 XVIII\~16. \plain \f1\i\lang1033\fs24 Sicut enim regnum dei\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 dimicem.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~527.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 XVI\~27. \plain \f1\i\lang1033\fs24 Abbas Joseph super illo uerbo Date locum ire. damus locum ire\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 quam declinat. \plain \f1\lang1033\fs24 CSEL 13, S.\~460\~f. 
\par \pard\fi0\li0\ql\ri0\sb0\sa63\itap0 (372\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) XVI\~16. \plain \f1\i\lang1033\fs24 Abbas Joseph. In tantum igitur non uult\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 iudices legis.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~451. XX\~5\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Abbas Panutius. Nouerit enim unusquisque\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 perstringi.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~558.\plain \f1\i\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  ... XXIV\~11.\plain \f1\i\lang1033\fs24  Noueris te in futuro\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 in hac uita in lucri detrimentiue consortio uel gaudio uel merore concuteris.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 CSEL 13, S.\~685.}

