\pard\fi0\li0\ql\ri0\sb0\sa63\itap0 \plain \f1\lang1033\fs24 373\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 374\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. (373\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) XIV\~34. \plain \f1\i\lang1033\fs24 Circumseptam uerberibus semitam suam uidit\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 eligere debeat nescit.\plain \f1\lang1033\fs24  CC Ser. lat. 143A, S.\~722\~f. IX\~35\endash 36. \plain \f1\i\lang1033\fs24 Sciendum est quia mundos\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 Deus non spernit.\plain \f1\lang1033\fs24  CC Ser. lat. 143, S.\~496\~f. VIII\~18. \plain \f1\i\lang1033\fs24 Ad contemplandum quippe\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 elongauit.\plain \f1\lang1033\fs24  CC Ser. lat. 143, S.\~406. VII\~15. \plain \f1\i\lang1033\fs24 Si etiam mens in deo forti intentione\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 conscendat.\plain \f1\lang1033\fs24  CC Ser. lat.\~143, S.\~346. XIV\~37. \plain \f1\i\lang1033\fs24 Plaga inimici percussi\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 feriamur.\plain \f1\lang1033\fs24  CC Ser. lat. 143A, S.\~725. V\~10. \plain \f1\i\lang1033\fs24 Quis nouit potestatem\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 gratia putatur.\plain \f1\lang1033\fs24  CC Ser. lat.\~143, S.\~228\~f. III\~9. \plain \f1\i\lang1033\fs24 Quisquis etiam dona percipit\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 destruitur.\plain \f1\lang1033\fs24  CC Ser. lat. 143, S.\~125. (373\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) XXXII\~1. \plain \f1\i\lang1033\fs24 Sancti uiri quanto apud deum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 uigilantior redit. Vnde salomon ait: cuncta temptaui\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 distat a recto.\plain \f1\lang1033\fs24  CC Ser. lat. 143B, S.\~1625\~f. (373\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) XXXII\~4. \plain \f1\i\lang1033\fs24 Nam cum iniustitie peccato\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 discrepauit a culpa.\plain \f1\lang1033\fs24  CC Ser. lat. 143B, S.\~1630. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Homiliae in evangelia}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpt. Hom. XV\~4. \plain \f1\i\lang1033\fs24 Terra autem bona fructum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 tribulationis purgat.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~106\~f. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. III\~9. \plain \f1\i\lang1033\fs24 Quis etiam dona percipit\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 desperatione destruitur.\plain \f1\lang1033\fs24  CC Ser. lat. 143, S.\~125. (374\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) X\~18. \plain \f1\i\lang1033\fs24 Et cum te consumptum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 retributione \plain \f2\lang1024\fs24 \u225 \'e1\plain \f1\i\lang1033\fs24 confi\plain \f2\lang1024\fs24 \u241 \'f1\plain \f1\i\lang1033\fs24 dit.\plain \f1\lang1033\fs24  CC Ser. lat. 143, S.\~561\~f. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Homiliae in evangelia}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. Hom. XI\~1\endash 3. \plain \f1\i\lang1033\fs24 Tesaurus autem celeste\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 perhorrescat. Qui ergo in pace\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 daremus. Fortis est ut mors\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 reddit.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~74\~ff. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Dialogi}}\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24 Exzerpt. III\~24. \plain \f1\i\lang1033\fs24 Caro enim ea que sunt spiritus\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 infirmetur.\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire le Grand\plain \f1\lang1033\fs24 : Dialogues, t. II, hg. v. A. \plain \f1\scaps\lang1033\fs24 de Vog\plain \f1\scaps\lang1033\fs24 \u252 \'fc\u233 \'e9\plain \f1\lang1033\fs24 , Paris 1979 (SC\~260), S.\~362\~ff. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. XXIII\~24. \plain \f1\i\lang1033\fs24 Electis suis deus iter asperum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 in patria.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1179\~f. \u9632 \'a6 \plain \f1\i\lang1033\fs24 Item nullus per gratiam uisitatur nisi prius per penam affligatur.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Homiliae in evangelia}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. Hom. XXXI\~7. \plain \f1\i\lang1033\fs24 Vsitata etenim culpa\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 cohacta cadit.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~274. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  Exzerpte. XXX\~18. \plain \f1\i\lang1033\fs24 Neque enim ad conflictum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 transimus.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1530. VIII\~35. \plain \f1\i\lang1033\fs24 Quamobrem suspendium elegit anima mea\plain \f1\lang1033\fs24 \~\u8230 \'85 (Iob 7,15). \plain \f1\i\lang1033\fs24 Quid per animam\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 humilitatis insecuntur.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~415. (374\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) XXIV\~11. \plain \f1\i\lang1033\fs24 Plerumque uero ipsi temptationum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 quanto magis assueti.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1210. III\~28. \plain \f1\i\lang1033\fs24 Sepe anticus hostis postquam\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 irrumpat.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~150. III\~31. \plain \f1\i\lang1033\fs24 Qui enim uere se humiliat\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 pensat.\plain \f1\lang1033\fs24  CC Ser. lat. 141, S.\~154. XXX\~18. \plain \f1\i\lang1033\fs24 Sciendum est quod .v. modis nos gule uitium temptat\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 deterius peccat.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1531. {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ambrosius Autpertus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Expositio in apocalypsin}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  II (3,11). \plain \f1\i\lang1033\fs24 Formidemus igitur in illis que accipimus\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 nouit irridere.\plain \f1\lang1033\fs24  CC Cont. med., S. 175. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Moralia in Job}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  XXX\~9. \plain \f1\i\lang1033\fs24 Vbi eras quando\plain \f1\lang1033\fs24 \~\u8230 \'85 (Iob 38,4). \plain \f1\i\lang1033\fs24 Necesse est ut unusquisque\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 per meritum\plain \f1\lang1033\fs24  (!)\plain \f1\i\lang1033\fs24  est factus. Vt ergo in te non destruam\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 quod fuimus.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1411\~f. XXVII\~37. \plain \f1\i\lang1033\fs24 In hoc itaque mundo\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 cognouimus perfecte.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1380. XXIV\~9. \plain \f1\i\lang1033\fs24 Et uere deliqui\plain \f1\lang1033\fs24 \~\u8230 \'85 (Iob\~33,27). \plain \f1\i\lang1033\fs24 Peccatores se plerumque confitentur\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 uere non dicit. Valde facile est cum peccatorem se quisque\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 cognoscimus culpam.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1203\~f. XXVI\~17. \plain \f1\i\lang1033\fs24 Proinde per humilitatis custodiam\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 non leuatur.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1286. XXIII 21 \plain \f1\i\lang1033\fs24 Neque enim quis presentis uite mala\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 necdum ualet.\plain \f1\lang1033\fs24  CC Ser. lat. 141B, S.\~1176. {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Cassianus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Collationes}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  XI\~10. \plain \f1\i\lang1033\fs24 Ideoque hisdem uitiis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 humana \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 seueritate condempnat.\plain \f1\lang1033\fs24  CSEL 13, S. 325. XX\~5. \plain \f1\i\lang1033\fs24 Tum demum preterita nobis uitiorum\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 passionesque depulse.\plain \f1\lang1033\fs24  CSEL 13, S. 559. XVI 27. \plain \f1\i\lang1033\fs24 Ioseph. Hec est natura ire\plain \f1\lang1033\fs24 \~\u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 conflagret.\plain \f1\lang1033\fs24  CSEL 13, S. 461. XVIII\~16. \plain \f1\i\lang1033\fs24 Abbas Piamun. Nisi enim mentem nostram uirtute\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85\~\plain \f1\i\lang1033\fs24 nos credimus.\plain \f1\lang1033\fs24  CSEL 13, S.\~526.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset2 Symbol;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

